// Related: postbash.go -- the posttool-bash checks
//
// VALIDATES: after a Bash call, a Go file the command just left unformatted is
// named, and a formatted, an older or a generated file is not.
// PREVENTS: a shell edit (sed, heredoc, scripted rename) reaching a commit
// misformatted because only a Write or an Edit was ever formatted, and the
// silent version of that check, where a tree it could not list read as clean.
package hookruntime

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

const (
	unformattedGo = "package sample\n\nvar  misaligned = 1\n"
	formattedGo   = "package sample\n\nvar aligned = 1\n"
)

// gitFixture is a throwaway checkout git status can answer for.
func gitFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	if output, err := exec.CommandContext(t.Context(), "git", "-C", root, "init", "-q").CombinedOutput(); err != nil {
		t.Fatalf("git init: %v\n%s", err, output)
	}
	return root
}

func probeBash(t *testing.T, root string) (int, string) {
	t.Helper()
	code, message, found := Probe("postBashGofmt", Payload{ToolName: "Bash", ToolInput: map[string]any{"command": "sed -i s/a/b/ pkg/*.go"}}, root)
	if !found {
		t.Fatal("postBashGofmt is not registered in nativeHookActions")
	}
	return code, message
}

func TestPostBashGofmtNamesTheFileTheCommandLeftUnformatted(t *testing.T) {
	root := gitFixture(t)
	writeHookFixture(t, root, "pkg/bad.go", unformattedGo)
	writeHookFixture(t, root, "pkg/good.go", formattedGo)

	code, message := probeBash(t, root)
	if code != 2 {
		t.Fatalf("code %d, want 2 so the agent is told:\n%s", code, message)
	}
	if !strings.Contains(message, "pkg/bad.go") {
		t.Errorf("the unformatted file is not named:\n%s", message)
	}
	if strings.Contains(message, "pkg/good.go") {
		t.Errorf("a formatted file is named:\n%s", message)
	}
	// It reports and never rewrites: the file may be another session's.
	body, err := os.ReadFile(filepath.Join(root, "pkg", "bad.go"))
	if err != nil {
		t.Fatal(err)
	}
	if string(body) != unformattedGo {
		t.Errorf("the check rewrote the file:\n%q", body)
	}
}

func TestPostBashGofmtLeavesAFileOutsideTheWindowAlone(t *testing.T) {
	root := gitFixture(t)
	writeHookFixture(t, root, "pkg/old.go", unformattedGo)
	earlier := time.Now().Add(-postBashWindow - time.Minute)
	if err := os.Chtimes(filepath.Join(root, "pkg", "old.go"), earlier, earlier); err != nil {
		t.Fatal(err)
	}

	if code, message := probeBash(t, root); code != 0 {
		t.Errorf("a file older than the window was judged (code %d):\n%s", code, message)
	}
}

func TestPostBashGofmtLeavesGeneratedSourceAlone(t *testing.T) {
	root := gitFixture(t)
	writeHookFixture(t, root, "pkg/gen.go", "// Code generated by sample. DO NOT EDIT.\n\n"+unformattedGo)

	if code, message := probeBash(t, root); code != 0 {
		t.Errorf("generated source was judged (code %d):\n%s", code, message)
	}
}

func TestPostBashGofmtSaysWhenItCouldNotListTheTree(t *testing.T) {
	root := t.TempDir() // no repository: git status fails
	writeHookFixture(t, root, "pkg/bad.go", unformattedGo)

	code, message := probeBash(t, root)
	if code != 2 || !strings.Contains(message, "did NOT check") {
		t.Errorf("an unlistable tree was not reported as unchecked (code %d):\n%s", code, message)
	}
}

// VALIDATES: an unformatted file the command does not name is said at code 0,
// and one it names through a parent directory blocks.
// PREVENTS: every session blocked after every command, with another session's
// unformatted file in its context, because the file changed inside the window.
func TestPostBashGofmtBlocksOnlyAFileTheCommandNames(t *testing.T) {
	root := gitFixture(t)
	writeHookFixture(t, root, "other/theirs.go", unformattedGo)

	code, message, _ := Probe("postBashGofmt", Payload{ToolName: "Bash", ToolInput: map[string]any{"command": "sed -i s/a/b/ pkg/x.go"}}, root)
	if code != 0 {
		t.Fatalf("a file the command does not name blocked (code %d):\n%s", code, message)
	}
	if !strings.Contains(message, "1 unformatted Go file(s)") || strings.Contains(message, "theirs.go") {
		t.Errorf("the unnamed file is not counted, or is named into the agent's view:\n%s", message)
	}

	code, message, _ = Probe("postBashGofmt", Payload{ToolName: "Bash", ToolInput: map[string]any{"command": "gopls rename ./other/ x y"}}, root)
	if code != 2 || !strings.Contains(message, "other/theirs.go") {
		t.Errorf("a file under a directory the command names did not block (code %d):\n%s", code, message)
	}
}
